// Помощники для #243006 (/publishconfirmation — текст по статусу). ПРОД, гость, только чтение:
// объявление не создаётся — в ответе GET business?id=eq.<id> подменяется только поле status; все не-GET — abort.
import { expect, Page, Request } from '@playwright/test';

export const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
export const LOAD = { timeout: 20_000 };
/** Существующее активное объявление на проде (проверено 04.11). Экран открывается по id и гостю. Если снято — это данные, не баг. */
export const LISTING_ID = process.env.QA_PUBCONF_LISTING_ID || '5832e079-87c7-49a8-9c24-97e7664dcba6';
/** Значения поля business.status на сайте (иврит, как в ответе сервера и в «סטטוס נוכחי»). */
export const STATUS = { pending: 'בהמתנה', active: 'פעיל' } as const;

/**
 * Блок записи + подмена статуса. Возвращает passed (не-GET, дошедшие до сервера — должно быть пусто)
 * и mocked (сколько ответов business подменено — должно быть > 0, иначе экран показывает реальный статус).
 */
export async function openWithStatus(page: Page, status: string) {
  const passed: string[] = [];
  const ctl = { mocked: 0, rows: 0 };
  await page.route('**/*', async (route) => {
    const req = route.request();
    if (!SAFE_METHODS.includes(req.method())) return route.abort('blockedbyclient');
    if (/\/rest\/v1\/business\?/.test(req.url()) && req.url().includes(`id=eq.${LISTING_ID}`)) {
      const response = await route.fetch();
      const json = await response.json();
      const rows = Array.isArray(json) ? json : [json];
      ctl.rows = rows.length;
      ctl.mocked++;
      return route.fulfill({ response, json: rows.map((r) => ({ ...r, status })) });
    }
    return route.fallback();
  });
  page.on('requestfinished', (r: Request) => {
    if (!SAFE_METHODS.includes(r.method())) passed.push(`${r.method()} ${r.url()}`);
  });

  await page.goto(`/publishconfirmation?id=${LISTING_ID}`);
  await expect(page.getByText('סטטוס נוכחי'), 'блок «סטטוס המודעה» загрузился').toBeVisible(LOAD);
  expect(ctl.rows, `объявление ${LISTING_ID} есть на сайте (иначе задай QA_PUBCONF_LISTING_ID)`).toBeGreaterThan(0);
  expect(ctl.mocked, 'ответ business подменён').toBeGreaterThan(0);
  await expect(page.getByText('מזהה עסק לא נמצא')).toHaveCount(0);
  await expect(page.getByText('מזהה מודעה')).toBeVisible();
  return { passed };
}

/** «סטטוס נוכחי:» — значение в той же строке блока. */
export async function expectCurrentStatus(page: Page, status: string) {
  const row = page.getByText('סטטוס נוכחי').locator('..');
  await expect(row, `«סטטוס נוכחי» = «${status}»`).toContainText(status);
}
